import { useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import {
    getMerchantUserDetail,
    getMerchantBindDeviceList,
    updateMerchantUserInfo,
    updateMerchantBindDevice,
    PlatformUserTypes
} from '@/apis/admin/platform-user'
import { getDeviceList, DeviceManagementTypes } from '@/apis/admin/device-management'

import {
    PageContainer,
    ProCard,
    ProDescriptions,
    ProTable
} from '@ant-design/pro-components'
import {
    Button,
    message,
    Tag,
    Space,
    Spin,
    Badge,
    Modal,
    Form,
    Input,
    Checkbox,
    Card,
    Row,
    Col,
    Descriptions,
    Select
} from 'antd'
import {
    ArrowLeftOutlined,
    EditOutlined,
    LinkOutlined,
    WalletOutlined,
    DatabaseOutlined,
    UserOutlined,
    ClockCircleOutlined,
    CheckCircleOutlined,
    DollarOutlined,
    LockOutlined,
    EyeOutlined
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'
import dayjs from 'dayjs'

// 商户状态映射
const merchantStatusMap: Record<number, { text: string; color: string }> = {
    1: { text: '启用', color: 'success' },
    2: { text: '禁用', color: 'error' },
}

// 商户身份映射
const identityTypeMap: Record<number, { text: string; color: string }> = {
    1: { text: '商户', color: 'blue' },
    2: { text: '运维人员', color: 'orange' },
}

// 设备状态映射
const deviceStatusMap: Record<number, { text: string; color: string }> = {
    1: { text: '在线', color: 'success' },
    2: { text: '离线', color: 'error' },
    3: { text: '故障', color: 'warning' },
    4: { text: '未激活', color: 'default' },
}

// 格口类型映射
const cabinetTypeMap: Record<number, string> = {
    1: '主柜',
    2: '副柜',
}

// 格式化时间
const formatTime = (time: string) => {
    if (!time) {
return '-'
}
    return dayjs(time).format('YYYY-MM-DD HH:mm:ss')
}

// 格式化金额
const formatMoney = (amount: number) => {
    return `¥${Number(amount || 0).toFixed(2)}`
}

const MerchantDetail: React.FC = () => {
    const { id } = useParams<{ id: string }>()
    const navigate = useNavigate()
    const [form] = Form.useForm()
    const [detail, setDetail] = useState<PlatformUserTypes.DetailMerchantUserRes | null>(null)
    const [bindDevices, setBindDevices] = useState<PlatformUserTypes.BindDeviceListMerchantDto[]>([])
    const [loading, setLoading] = useState(true)
    const [editModalVisible, setEditModalVisible] = useState(false)
    const [bindModalVisible, setBindModalVisible] = useState(false)
    const [deviceList, setDeviceList] = useState<DeviceManagementTypes.DeviceListDto[]>([])
    const [filteredDeviceList, setFilteredDeviceList] = useState<DeviceManagementTypes.DeviceListDto[]>([])
    const [selectedDevices, setSelectedDevices] = useState<number[]>([])
    const [confirmLoading, setConfirmLoading] = useState(false)
    const [filterProvince, setFilterProvince] = useState<number | undefined>()
    const [filterCity, setFilterCity] = useState<number | undefined>()
    const [filterArea, setFilterArea] = useState<number | undefined>()

    const merchantId = Number(id) || 0

    // 获取商户详情
    const fetchDetail = async () => {
        if (!merchantId) {
return
}
        try {
            setLoading(true)
            const res = await getMerchantUserDetail(merchantId)
            if (res.code === ResultEnum.SUCCESS && res.data) {
                setDetail(res.data)
            } else {
                message.error('获取商户详情失败')
            }
        } catch (e) {
            console.error('获取商户详情失败:', e)
            message.error('获取商户详情失败')
        } finally {
            setLoading(false)
        }
    }

    // 获取绑定设备列表
    const fetchBindDevices = async () => {
        if (!merchantId) {
return
}
        try {
            const res = await getMerchantBindDeviceList(merchantId)
            if (res.code === ResultEnum.SUCCESS && res.data?.List) {
                setBindDevices(res.data.List)
            }
        } catch (e) {
            console.error('获取绑定设备失败:', e)
        }
    }

    useEffect(() => {
        fetchDetail()
        fetchBindDevices()
    }, [merchantId])

    // 打开编辑弹窗
    const handleOpenEdit = () => {
        if (!detail) {
return
}
        const identityType: string[] = []
        if (detail.identityType & 1) {
identityType.push('franchisee')
}
        if (detail.identityType & 2) {
identityType.push('operator')
}

        form.setFieldsValue({
            merchantName: detail.merchantName,
            contactUser: detail.contactUser,
            contactPhone: detail.contactPhone,
            idCard: detail.idCard,
            businessLicense: detail.businessLicense,
            remark: detail.remark,
            identityType
        })
        setEditModalVisible(true)
    }

    // 保存商户信息
    const handleSaveEdit = async () => {
        try {
            const values = await form.validateFields()
            setConfirmLoading(true)

            const identityType: number[] = []
            if (values.identityType?.includes('franchisee')) {
identityType.push(1)
}
            if (values.identityType?.includes('operator')) {
identityType.push(2)
}

            const res = await updateMerchantUserInfo(merchantId, {
                userId: merchantId,
                merchantName: values.merchantName,
                contactUser: values.contactUser,
                contactPhone: values.contactPhone,
                idCard: values.idCard,
                businessLicense: values.businessLicense,
                remark: values.remark,
                identityType
            })

            if (res.code === ResultEnum.SUCCESS) {
                message.success('商户信息已保存')
                setEditModalVisible(false)
                fetchDetail()
            } else {
                message.error(res.message || '保存失败')
            }
        } catch (e) {
            console.error(e)
        } finally {
            setConfirmLoading(false)
        }
    }

    // 打开绑定设备弹窗
    const handleOpenBind = async () => {
        setBindModalVisible(true)
        setSelectedDevices(bindDevices.map(d => d.deviceId))
        setFilterProvince(undefined)
        setFilterCity(undefined)
        setFilterArea(undefined)
        try {
            const res = await getDeviceList({ pageSize: 1000 })
            if (res.code === ResultEnum.SUCCESS && res.data?.list) {
                setDeviceList(res.data.list)
                setFilteredDeviceList(res.data.list)
            }
        } catch (e) {
            console.error('加载设备列表失败:', e)
        }
    }

    // 保存绑定设备
    const handleSaveBind = async () => {
        try {
            setConfirmLoading(true)
            const res = await updateMerchantBindDevice(merchantId, {
                userId: merchantId,
                deviceIdArr: selectedDevices
            })

            if (res.code === ResultEnum.SUCCESS) {
                message.success('绑定关系已更新')
                setBindModalVisible(false)
                fetchBindDevices()
            } else {
                message.error(res.message || '保存失败')
            }
        } catch (e) {
            console.error(e)
        } finally {
            setConfirmLoading(false)
        }
    }

    // 处理设备选择
    const handleDeviceSelect = (deviceId: number, checked: boolean) => {
        if (checked) {
            setSelectedDevices([...selectedDevices, deviceId])
        } else {
            setSelectedDevices(selectedDevices.filter(id => id !== deviceId))
        }
    }

    // 获取省份选项（从设备列表提取）
    const getProvinceOptions = () => {
        const provinces = [...new Map(deviceList.map(d => [d.provinceId, d.provinceId])).entries()]
        return provinces.map(([id]) => ({ label: `省份${id}`, value: id }))
    }

    // 获取城市选项（从设备列表提取）
    const getCityOptions = () => {
        if (!filterProvince) {
return []
}
        const cities = [...new Map(deviceList.filter(d => d.provinceId === filterProvince).map(d => [d.cityId, d.cityId])).entries()]
        return cities.map(([id]) => ({ label: `城市${id}`, value: id }))
    }

    // 获取区县选项（从设备列表提取）
    const getAreaOptions = () => {
        if (!filterCity) {
return []
}
        const areas = [...new Map(deviceList.filter(d => d.cityId === filterCity).map(d => [d.areaId, d.areaId])).entries()]
        return areas.map(([id]) => ({ label: `区县${id}`, value: id }))
    }

    // 处理省份筛选变化
    const handleProvinceChange = (value?: number) => {
        setFilterProvince(value)
        setFilterCity(undefined)
        setFilterArea(undefined)
        filterDevices(value, undefined, undefined)
    }

    // 处理城市筛选变化
    const handleCityChange = (value?: number) => {
        setFilterCity(value)
        setFilterArea(undefined)
        filterDevices(filterProvince, value, undefined)
    }

    // 处理区县筛选变化
    const handleAreaChange = (value?: number) => {
        setFilterArea(value)
        filterDevices(filterProvince, filterCity, value)
    }

    // 筛选设备
    const filterDevices = (province?: number, city?: number, area?: number) => {
        let filtered = deviceList
        if (province) {
            filtered = filtered.filter(d => d.provinceId === province)
        }
        if (city) {
            filtered = filtered.filter(d => d.cityId === city)
        }
        if (area) {
            filtered = filtered.filter(d => d.areaId === area)
        }
        setFilteredDeviceList(filtered)
    }

    // 渲染身份标签
    const renderIdentityTags = (identityType: number) => {
        const types: number[] = []
        if (identityType & 1) {
types.push(1)
}
        if (identityType & 2) {
types.push(2)
}

        return (
            <Space size="small">
                {types.map(type => {
                    const identity = identityTypeMap[type]
                    return (
                        <Tag key={type} color={identity?.color || 'default'}>
                            {identity?.text || '未知'}
                        </Tag>
                    )
                })}
            </Space>
        )
    }

    if (loading) {
        return (
            <PageContainer>
                <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: 400 }}>
                    <Spin size="large" tip="加载中..." />
                </div>
            </PageContainer>
        )
    }

    if (!detail) {
        return (
            <PageContainer>
                <div style={{ textAlign: 'center', padding: 40 }}>
                    <p>商户不存在或已被删除</p>
                    <Button type="primary" onClick={() => navigate('/user/merchant')}>
                        返回商户列表
                    </Button>
                </div>
            </PageContainer>
        )
    }

    return (
        <PageContainer
            header={{
                title: (
                    <Space>
                        <Button
                            type="text"
                            icon={<ArrowLeftOutlined />}
                            onClick={() => navigate('/user/merchant')}
                        >
                            返回列表
                        </Button>
                        <span style={{ fontSize: 20, fontWeight: 600 }}>商户详情</span>
                    </Space>
                ),
                breadcrumb: undefined,
            }}
        >
            <Space direction="vertical" size="large" style={{ width: '100%' }}>
                {/* 操作栏 */}
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <Button
                        type="default"
                        icon={<ArrowLeftOutlined />}
                        onClick={() => navigate('/user/merchant')}
                    >
                        返回商户列表
                    </Button>
                    <Space>
                        <Button
                            icon={<EditOutlined />}
                            onClick={handleOpenEdit}
                        >
                            编辑商户
                        </Button>
                        <Button
                            type="primary"
                            icon={<LinkOutlined />}
                            onClick={handleOpenBind}
                        >
                            编辑绑定
                        </Button>
                    </Space>
                </div>

                {/* 基本信息卡片 */}
                <ProCard
                    title={
                        <Space>
                            <UserOutlined style={{ color: '#1890ff' }} />
                            基本信息
                            <Tag color={merchantStatusMap[detail.status]?.color}>
                                {merchantStatusMap[detail.status]?.text}
                            </Tag>
                        </Space>
                    }
                    bordered
                    headerBordered
                >
                    <ProDescriptions
                        column={2}
                        dataSource={detail}
                        columns={[
                            {
                                title: '商户ID',
                                key: 'id',
                                dataIndex: 'id',
                                render: (text: any) => (
                                    <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 600 }}>
                                        {text as string}
                                    </span>
                                ),
                            },
                            {
                                title: '商户名称',
                                key: 'merchantName',
                                dataIndex: 'merchantName',
                            },
                            {
                                title: '联系人姓名',
                                key: 'contactUser',
                                dataIndex: 'contactUser',
                            },
                            {
                                title: '联系电话',
                                key: 'contactPhone',
                                dataIndex: 'contactPhone',
                            },
                            {
                                title: '身份证号',
                                key: 'idCard',
                                dataIndex: 'idCard',
                                render: (text: any) => text || '-',
                            },
                            {
                                title: '营业执照号',
                                key: 'businessLicense',
                                dataIndex: 'businessLicense',
                                render: (text: any) => text || '-',
                            },
                            {
                                title: '商户身份',
                                key: 'identityType',
                                dataIndex: 'identityType',
                                render: (text: any) => renderIdentityTags(text as number),
                            },
                            {
                                title: '创建时间',
                                key: 'createdAt',
                                dataIndex: 'createdAt',
                                render: (text: any) => formatTime(text as string),
                            },
                            {
                                title: '备注',
                                key: 'remark',
                                dataIndex: 'remark',
                                span: 2,
                                render: (text: any) => text || '-',
                            },
                        ]}
                    />
                </ProCard>

                {/* 钱包详情卡片 */}
                <ProCard
                    title={
                        <Space>
                            <WalletOutlined style={{ color: '#1890ff' }} />
                            钱包详情
                        </Space>
                    }
                    bordered
                    headerBordered
                    extra={
                        <Button size="small" icon={<ClockCircleOutlined />}>
                            提现记录
                        </Button>
                    }
                >
                    <Row gutter={16}>
                        <Col span={8}>
                            <Card
                                style={{
                                    background: 'linear-gradient(135deg, #10B981, #059669)',
                                    border: 'none',
                                    color: '#fff'
                                }}
                            >
                                <div style={{ fontSize: 13, opacity: 0.9, marginBottom: 8 }}>
                                    <DollarOutlined style={{ marginRight: 6 }} />
                                    可提现金额
                                </div>
                                <div style={{ fontSize: 28, fontWeight: 600 }}>
                                    {formatMoney(detail.withdrawAbleAmount)}
                                </div>
                            </Card>
                        </Col>
                        <Col span={8}>
                            <Card
                                style={{
                                    background: 'linear-gradient(135deg, #2563EB, #1D4ED8)',
                                    border: 'none',
                                    color: '#fff'
                                }}
                            >
                                <div style={{ fontSize: 13, opacity: 0.9, marginBottom: 8 }}>
                                    <CheckCircleOutlined style={{ marginRight: 6 }} />
                                    已提现金额
                                </div>
                                <div style={{ fontSize: 28, fontWeight: 600 }}>
                                    {formatMoney(detail.withdrawnAmount)}
                                </div>
                            </Card>
                        </Col>
                        <Col span={8}>
                            <Card
                                style={{
                                    background: 'linear-gradient(135deg, #F59E0B, #D97706)',
                                    border: 'none',
                                    color: '#fff'
                                }}
                            >
                                <div style={{ fontSize: 13, opacity: 0.9, marginBottom: 8 }}>
                                    <LockOutlined style={{ marginRight: 6 }} />
                                    冻结中金额
                                </div>
                                <div style={{ fontSize: 28, fontWeight: 600 }}>
                                    {formatMoney(detail.frozenAmount)}
                                </div>
                            </Card>
                        </Col>
                    </Row>
                </ProCard>

                {/* 绑定设备列表 */}
                <ProCard
                    title={
                        <Space>
                            <DatabaseOutlined style={{ color: '#1890ff' }} />
                            绑定设备列表
                            <span style={{ fontSize: 12, color: '#64748B' }}>
                                共 <b>{bindDevices.length}</b> 台设备
                            </span>
                        </Space>
                    }
                    bordered
                    headerBordered
                >
                    <ProTable<PlatformUserTypes.BindDeviceListMerchantDto>
                        columns={[
                            {
                                title: '设备编号',
                                key: 'deviceImei',
                                dataIndex: 'deviceImei',
                                width: 160,
                                render: (text: any) => (
                                    <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>
                                        {text as string}
                                    </span>
                                ),
                            },
                            {
                                title: '设备名称',
                                key: 'deviceName',
                                dataIndex: 'deviceName',
                                width: 140,
                            },
                            {
                                title: '所属地区',
                                key: 'areaName',
                                dataIndex: 'areaName',
                                width: 200,
                                render: (_: any, record: any) => (
                                    <span>
                                        {record.provinceName}{record.cityName}{record.areaName}
                                    </span>
                                ),
                            },
                            {
                                title: '格口配置',
                                key: 'cabinetType',
                                dataIndex: 'cabinetType',
                                width: 100,
                                render: (text: any) => cabinetTypeMap[text as number] || '未知',
                            },
                            {
                                title: '在线状态',
                                key: 'status',
                                dataIndex: 'status',
                                width: 100,
                                render: (status: any) => {
                                    const s = deviceStatusMap[status as number]
                                    return <Badge status={s.color as any} text={s.text} />
                                },
                            },
                            {
                                title: '操作',
                                key: 'option',
                                fixed: 'right',
                                width: 100,
                                render: (_: any, record: any) => (
                                    <Button
                                        type="link"
                                        size="small"
                                        icon={<EyeOutlined />}
                                        onClick={() => navigate(`/device/detail/${record.deviceId}`)}
                                    >
                                        查看详情
                                    </Button>
                                ),
                            },
                        ]}
                        dataSource={bindDevices}
                        rowKey="id"
                        pagination={{ pageSize: 10 }}
                        search={false}
                        options={false}
                        scroll={{ x: 800 }}
                        size="small"
                    />
                </ProCard>
            </Space>

            {/* 编辑商户信息弹窗 */}
            <Modal
                title="编辑商户信息"
                open={editModalVisible}
                onCancel={() => setEditModalVisible(false)}
                onOk={handleSaveEdit}
                confirmLoading={confirmLoading}
                width={560}
            >
                <Form
                    form={form}
                    layout="vertical"
                    style={{ marginTop: 16 }}
                >
                    <Form.Item
                        label="商户ID"
                    >
                        <Input value={detail.id} disabled style={{ background: '#F1F5F9' }} />
                    </Form.Item>
                    <Form.Item
                        label="商户名称"
                        name="merchantName"
                        rules={[{ required: true, message: '请输入商户名称' }]}
                    >
                        <Input placeholder="请输入商户名称" />
                    </Form.Item>
                    <Row gutter={16}>
                        <Col span={12}>
                            <Form.Item
                                label="联系人姓名"
                                name="contactUser"
                                rules={[{ required: true, message: '请输入联系人姓名' }]}
                            >
                                <Input placeholder="请输入联系人姓名" />
                            </Form.Item>
                        </Col>
                        <Col span={12}>
                            <Form.Item
                                label="联系电话"
                                name="contactPhone"
                                rules={[
                                    { required: true, message: '请输入联系电话' },
                                    { pattern: /^1[3-9]\d{9}$/, message: '请输入正确的手机号' }
                                ]}
                            >
                                <Input placeholder="请输入联系电话" />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Form.Item
                        label="商户身份"
                        name="identityType"
                        rules={[{ required: true, message: '请至少选择一种商户身份' }]}
                    >
                        <Checkbox.Group>
                            <Checkbox value="franchisee">
                                <Tag color="blue">商户</Tag>
                            </Checkbox>
                            <Checkbox value="operator">
                                <Tag color="orange">运维人员</Tag>
                            </Checkbox>
                        </Checkbox.Group>
                    </Form.Item>
                    <p style={{ fontSize: 12, color: '#999', marginTop: -8, marginBottom: 16 }}>可同时选择多种身份</p>
                    <Row gutter={16}>
                        <Col span={12}>
                            <Form.Item
                                label="身份证号"
                                name="idCard"
                            >
                                <Input placeholder="请输入身份证号" />
                            </Form.Item>
                        </Col>
                        <Col span={12}>
                            <Form.Item
                                label="营业执照号"
                                name="businessLicense"
                            >
                                <Input placeholder="请输入营业执照号" />
                            </Form.Item>
                        </Col>
                    </Row>
                    <Form.Item
                        label="备注"
                        name="remark"
                    >
                        <Input.TextArea rows={3} placeholder="请输入备注信息" />
                    </Form.Item>
                </Form>
            </Modal>

            {/* 编辑绑定弹窗 */}
            <Modal
                title="编辑绑定设备"
                open={bindModalVisible}
                onCancel={() => setBindModalVisible(false)}
                onOk={handleSaveBind}
                confirmLoading={confirmLoading}
                width={720}
            >
                <div style={{ marginBottom: 12 }}>
                    <p style={{ fontSize: 13, color: '#64748B' }}>
                        勾选要绑定的设备，取消勾选则解绑该设备
                    </p>
                </div>

                {/* 省市区筛选 */}
                <Card size="small" style={{ background: '#F8FAFC', marginBottom: 16 }}>
                    <Row gutter={12}>
                        <Col span={8}>
                            <Select
                                placeholder="选择省份"
                                value={filterProvince}
                                onChange={handleProvinceChange}
                                style={{ width: '100%' }}
                                allowClear
                            >
                                {getProvinceOptions().map(opt => (
                                    <Select.Option key={opt.value} value={opt.value}>
                                        {opt.label}
                                    </Select.Option>
                                ))}
                            </Select>
                        </Col>
                        <Col span={8}>
                            <Select
                                placeholder="选择城市"
                                value={filterCity}
                                onChange={handleCityChange}
                                style={{ width: '100%' }}
                                allowClear
                                disabled={!filterProvince}
                            >
                                {getCityOptions().map(opt => (
                                    <Select.Option key={opt.value} value={opt.value}>
                                        {opt.label}
                                    </Select.Option>
                                ))}
                            </Select>
                        </Col>
                        <Col span={8}>
                            <Select
                                placeholder="选择区县"
                                value={filterArea}
                                onChange={handleAreaChange}
                                style={{ width: '100%' }}
                                allowClear
                                disabled={!filterCity}
                            >
                                {getAreaOptions().map(opt => (
                                    <Select.Option key={opt.value} value={opt.value}>
                                        {opt.label}
                                    </Select.Option>
                                ))}
                            </Select>
                        </Col>
                    </Row>
                    <div style={{ marginTop: 12, fontSize: 12, color: '#64748B' }}>
                        共 <b>{filteredDeviceList.length}</b> 台设备
                        {selectedDevices.length > 0 && (
                            <span style={{ marginLeft: 16, color: '#2563EB' }}>
                                已选择 <b>{selectedDevices.length}</b> 台
                            </span>
                        )}
                    </div>
                </Card>

                {/* 设备列表 */}
                <Card
                    size="small"
                    style={{ background: '#F8FAFC', maxHeight: 320, overflow: 'auto' }}
                >
                    {filteredDeviceList.length === 0 ? (
                        <div style={{ textAlign: 'center', color: '#999', padding: 40 }}>
                            {deviceList.length === 0 ? '暂无设备数据' : '请先选择地区筛选设备'}
                        </div>
                    ) : (
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                            {filteredDeviceList.map(device => {
                                const isBound = selectedDevices.includes(device.id)
                                return (
                                    <label
                                        key={device.id}
                                        style={{
                                            display: 'flex',
                                            alignItems: 'center',
                                            gap: 12,
                                            padding: 12,
                                            background: isBound ? '#EFF6FF' : '#fff',
                                            border: `1px solid ${isBound ? '#2563EB' : '#E2E8F0'}`,
                                            borderRadius: 8,
                                            cursor: 'pointer',
                                            transition: 'all 0.2s'
                                        }}
                                    >
                                        <Checkbox
                                            checked={isBound}
                                            onChange={(e) => handleDeviceSelect(device.id, e.target.checked)}
                                        />
                                        <div style={{ flex: 1 }}>
                                            <div style={{ fontSize: 13, fontWeight: 500, marginBottom: 2 }}>
                                                {device.deviceName || device.imei}
                                                <span style={{ color: '#64748B', fontWeight: 400, marginLeft: 8 }}>
                                                    ({device.imei})
                                                </span>
                                            </div>
                                            <div style={{ fontSize: 12, color: '#64748B' }}>
                                                {device.provinceId}{device.cityId}{device.areaId}
                                                {device.communityId && ` · ${device.communityId}`}
                                            </div>
                                        </div>
                                        {isBound && (
                                            <Tag color="blue">已绑定</Tag>
                                        )}
                                    </label>
                                )
                            })}
                        </div>
                    )}
                </Card>
            </Modal>
        </PageContainer>
    )
}

export default MerchantDetail